import boto3
import os

def get_transcribe_client():
    return boto3.client("transcribe", region_name=os.environ.get("AWS_REGION", "us-east-1"))

def get_s3_client():
    return boto3.client("s3", region_name=os.environ.get("AWS_REGION", "us-east-1"))

def get_translate_client():
    return boto3.client("translate", region_name=os.environ.get("AWS_REGION", "us-east-1"))

def get_comprehend_client():
    return boto3.client("comprehend", region_name=os.environ.get("AWS_REGION", "us-east-1"))

def get_bedrock_runtime_client():
    # Using a generic client for Bedrock, assuming an embedding model will be called
    return boto3.client("bedrock-runtime", region_name=os.environ.get("AWS_REGION", "us-east-1"))

from dataclasses import dataclass
from typing import List, Dict, Any, Optional

@dataclass
class TranscriptionRequest:
    job_name: str
    media_uri: str
    media_format: str
    language_code: str
    output_bucket: str
    diarization_enabled: bool = False
    show_speaker_labels: bool = False
    show_alternatives: bool = False
    max_speakers: int = 2

@dataclass
class TranscriptionJobStatus:
    job_name: str
    status: str
    transcript_file_uri: Optional[str] = None
    failure_reason: Optional[str] = None

@dataclass
class TranscriptionResult:
    job_name: str
    status: str
    transcript_text: Optional[str] = None
    word_timestamps: Optional[List[Dict[str, Any]]] = None
    segments: Optional[List[Dict[str, Any]]] = None
    speaker_labels: Optional[List[Dict[str, Any]]] = None

@dataclass
class TranslatedSegment:
    original_text: str
    translated_text: str
    source_language: str
    target_language: str

@dataclass
class ModerationResult:
    text: str
    moderation_labels: List[Dict[str, Any]]

@dataclass
class SummaryResult:
    original_text: str
    summary_text: str

@dataclass
class EmbeddingResult:
    segment_text: str
    embedding: List[float]

import os
from speech_client import get_transcribe_client, get_s3_client
from speech_models import TranscriptionRequest

AWS_S3_BUCKET_NAME = os.environ.get("AWS_S3_BUCKET_NAME")

def upload_audio_to_s3(file_path: str, object_name: str) -> str:
    s3_client = get_s3_client()
    try:
        s3_client.upload_file(file_path, AWS_S3_BUCKET_NAME, object_name)
        print(f"File {file_path} uploaded to s3://{AWS_S3_BUCKET_NAME}/{object_name}")
        return f"s3://{AWS_S3_BUCKET_NAME}/{object_name}"
    except Exception as e:
        print(f"Error uploading file to S3: {e}")
        raise

def submit_transcription_job(request: TranscriptionRequest):
    transcribe_client = get_transcribe_client()
    try:
        response = transcribe_client.start_transcription_job(
            TranscriptionJobName=request.job_name,
            LanguageCode=request.language_code,
            MediaFormat=request.media_format,
            Media={
                'MediaFileUri': request.media_uri
            },
            OutputBucketName=request.output_bucket,
            Settings={
                'ShowSpeakerLabels': request.show_speaker_labels,
                'MaxSpeakerLabels': request.max_speakers if request.show_speaker_labels else 0,
            }
        )
        print(f"Transcription job {request.job_name} started: {response['TranscriptionJob']['TranscriptionJobStatus']}")
        return response['TranscriptionJob']
    except Exception as e:
        print(f"Error starting transcription job: {e}")
        raise

import time
import requests
from speech_client import get_transcribe_client
from speech_models import TranscriptionJobStatus, TranscriptionResult

def poll_transcription_job(job_name: str, interval_seconds: int = 10, max_retries: int = 60) -> TranscriptionJobStatus:
    transcribe_client = get_transcribe_client()
    retries = 0
    while retries < max_retries:
        try:
            response = transcribe_client.get_transcription_job(TranscriptionJobName=job_name)
            job = response['TranscriptionJob']
            status = job['TranscriptionJobStatus']
            transcript_file_uri = job.get('Transcript', {}).get('TranscriptFileUri')
            failure_reason = job.get('FailureReason')

            print(f"Transcription job {job_name} status: {status}")
            if status == 'COMPLETED':
                return TranscriptionJobStatus(job_name=job_name, status=status, transcript_file_uri=transcript_file_uri)
            elif status == 'FAILED':
                return TranscriptionJobStatus(job_name=job_name, status=status, failure_reason=failure_reason)

            time.sleep(interval_seconds)
            retries += 1
        except Exception as e:
            print(f"Error polling transcription job: {e}")
            raise
    return TranscriptionJobStatus(job_name=job_name, status="TIMEOUT", failure_reason="Max retries reached")

def get_transcript_content(transcript_uri: str) -> str:
    try:
        response = requests.get(transcript_uri)
        response.raise_for_status()
        return response.text
    except requests.exceptions.RequestException as e:
        print(f"Error fetching transcript from URI {transcript_uri}: {e}")
        raise

def get_transcription_result(job_name: str) -> TranscriptionResult:
    job_status = poll_transcription_job(job_name)
    if job_status.status == 'COMPLETED' and job_status.transcript_file_uri:
        transcript_json_content = get_transcript_content(job_status.transcript_file_uri)
        # In a real scenario, you'd parse the JSON to extract transcript_text, word_timestamps, etc.
        # For this exercise, we'll return the raw JSON content as the text for simplicity.
        # A more robust implementation would parse this JSON into the TranscriptionResult dataclass.
        return TranscriptionResult(
            job_name=job_name,
            status=job_status.status,
            transcript_text=transcript_json_content, # Simplified: returning raw JSON for demonstration
            word_timestamps=None, # Requires parsing the JSON output
            segments=None, # Requires parsing the JSON output
            speaker_labels=None # Requires parsing the JSON output
        )
    else:
        return TranscriptionResult(
            job_name=job_name,
            status=job_status.status,
            transcript_text=None,
            word_timestamps=None,
            segments=None,
            speaker_labels=None
        )

import os
from speech_client import get_transcribe_client
from speech_models import TranscriptionRequest, TranscriptionResult
from poll_transcription import poll_transcription_job, get_transcript_content
import json

def submit_diarized_transcription_job(request: TranscriptionRequest):
    transcribe_client = get_transcribe_client()
    try:
        response = transcribe_client.start_transcription_job(
            TranscriptionJobName=request.job_name,
            LanguageCode=request.language_code,
            MediaFormat=request.media_format,
            Media={
                'MediaFileUri': request.media_uri
            },
            OutputBucketName=request.output_bucket,
            Settings={
                'ShowSpeakerLabels': True, # Explicitly enable speaker labels for diarization
                'MaxSpeakerLabels': request.max_speakers,
                'ChannelIdentification': False # Assuming single channel for diarization
            }
        )
        print(f"Diarized transcription job {request.job_name} started: {response['TranscriptionJob']['TranscriptionJobStatus']}")
        return response['TranscriptionJob']
    except Exception as e:
        print(f"Error starting diarized transcription job: {e}")
        raise

def get_diarized_transcript_result(job_name: str) -> TranscriptionResult:
    job_status = poll_transcription_job(job_name)
    if job_status.status == 'COMPLETED' and job_status.transcript_file_uri:
        transcript_json_content = get_transcript_content(job_status.transcript_file_uri)
        transcript_data = json.loads(transcript_json_content)

        transcript_text = transcript_data['results']['transcripts'][0]['transcript']
        segments = []
        speaker_labels = []

        # Extracting segments and speaker labels
        if 'speaker_labels' in transcript_data['results']:
            for segment in transcript_data['results']['speaker_labels']['segments']:
                segments.append(segment)
            for item in transcript_data['results']['items']:
                if 'speaker_label' in item:
                    speaker_labels.append({
                        'start_time': item.get('start_time'),
                        'end_time': item.get('end_time'),
                        'speaker_label': item['speaker_label'],
                        'content': item['alternatives'][0]['content']
                    })

        return TranscriptionResult(
            job_name=job_name,
            status=job_status.status,
            transcript_text=transcript_text,
            word_timestamps=None, # Not directly extracted in this simplified example for diarization
            segments=segments,
            speaker_labels=speaker_labels
        )
    else:
        return TranscriptionResult(
            job_name=job_name,
            status=job_status.status,
            transcript_text=None,
            word_timestamps=None,
            segments=None,
            speaker_labels=None
        )

